/* Symbols generated by EMBED_FILES in CMakeLists.txt */
extern const uint8_t _binary_audio_wav_start[];
extern const uint8_t _binary_audio_wav_end[];

#define AUDIO_BIT_WIDTH I2S_DATA_BIT_WIDTH_16BIT
#define AUDIO_SLOT_MODE  I2S_SLOT_MODE_MONO
#define AUDIO_CHUNK_MS   200
#define AUDIO_VOLUME_SCALE 2
#define AUDIO_VOLUME_DIVISOR 4
#define AUDIO_DMA_DESC_NUM   8
#define AUDIO_DMA_FRAME_NUM  512
#define AUDIO_FILEPATH_MAX   192

static const char *TAG = "audio_player";

static i2s_chan_handle_t tx_chan;

/* Shared state */
static SemaphoreHandle_t audio_mutex = NULL;
static char current_filepath[AUDIO_FILEPATH_MAX] = {0};
static bool tx_channel_enabled = false;
typedef enum {
    AUDIO_IDLE,
    AUDIO_EMBEDDED,
    AUDIO_SD,
} audio_mode_t;
static audio_mode_t requested_mode = AUDIO_IDLE;
static uint32_t request_generation = 0;
static bool loop_sd = false;
static atomic_uint volume_percent = 50;

static bool request_is_current(audio_mode_t mode, uint32_t generation)
{
    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    bool current = requested_mode == mode && request_generation == generation;
    xSemaphoreGive(audio_mutex);
    return current;
}

/* WAV helpers */
static uint16_t read_le16(const uint8_t *p)
{
    return (uint16_t)((p[1] << 8) | p[0]);
}

static uint32_t read_le32(const uint8_t *p)
{
    return ((uint32_t)p[3] << 24) | ((uint32_t)p[2] << 16) | ((uint32_t)p[1] << 8) | p[0];
}

static const uint8_t *audio_parse_wav(const uint8_t *wav, size_t wav_size,
                                       uint16_t *num_channels,
                                       uint32_t *sample_rate,
                                       uint16_t *bits_per_sample,
                                       uint32_t *data_size)
{
    if (wav_size < 44) return NULL;
    if (memcmp(wav, "RIFF", 4) != 0) return NULL;
    if (memcmp(wav + 8, "WAVE", 4) != 0) return NULL;

    size_t pos = 12;
    while (pos + 8 <= wav_size) {
        uint32_t chunk_size = read_le32(wav + pos + 4);
        size_t chunk_data_pos = pos + 8;
        if (chunk_size > wav_size - chunk_data_pos) return NULL;
        if (memcmp(wav + pos, "fmt ", 4) == 0) {
            if (chunk_size < 16) return NULL;
            if (read_le16(wav + pos + 8) != 1) return NULL; /* PCM only */
            *num_channels = read_le16(wav + pos + 10);
            *sample_rate = read_le32(wav + pos + 12);
            *bits_per_sample = read_le16(wav + pos + 22);
            pos = chunk_data_pos + chunk_size + (chunk_size & 1U);
        } else if (memcmp(wav + pos, "data", 4) == 0) {
            *data_size = chunk_size;
            return wav + chunk_data_pos;
        } else {
            pos = chunk_data_pos + chunk_size + (chunk_size & 1U);
        }
    }
    return NULL;
}

static int16_t convert_sample(const uint8_t *frame, uint16_t num_channels)
{
    int16_t sample;
    if (num_channels == 1) {
        sample = (int16_t)((frame[0] | (frame[1] << 8)) & 0xFFFF);
    } else {
        int16_t left = (int16_t)((frame[0] | (frame[1] << 8)) & 0xFFFF);
        int16_t right = (int16_t)((frame[2] | (frame[3] << 8)) & 0xFFFF);
        sample = (int16_t)((left + right) / 2);
    }
    sample = (int16_t)((sample * (int)atomic_load(&volume_percent)) / 100);
    if (sample > 30000) sample = 30000;
    else if (sample < -30000) sample = -30000;
    return sample;
}

static void stop_output_channel(void)
{
    if (!tx_channel_enabled) return;

    esp_err_t err = i2s_channel_disable(tx_chan);
    if (err == ESP_OK || err == ESP_ERR_INVALID_STATE) {
        tx_channel_enabled = false;
    } else {
        ESP_LOGW(TAG, "Failed to disable I2S output: %s", esp_err_to_name(err));
    }
}

static void start_output_channel(void)
{
    ESP_ERROR_CHECK(i2s_channel_enable(tx_chan));
    tx_channel_enabled = true;
}

static bool write_pcm(const int16_t *samples, size_t count,
                      audio_mode_t mode, uint32_t generation)
{
    const uint8_t *data = (const uint8_t *)samples;
    size_t remaining = count * sizeof(*samples);
    while (remaining > 0) {
        if (!request_is_current(mode, generation)) return false;
        size_t written = 0;
        esp_err_t err = i2s_channel_write(tx_chan, data, remaining, &written,
                                          pdMS_TO_TICKS(100));
        if (err != ESP_OK && err != ESP_ERR_TIMEOUT) {
            ESP_LOGE(TAG, "I2S write failed: %s", esp_err_to_name(err));
            return false;
        }
        data += written;
        remaining -= written;
    }
    return true;
}

static void reconfigure_sample_rate(uint32_t sample_rate)
{
    stop_output_channel();
    i2s_std_clk_config_t clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(sample_rate);
    ESP_ERROR_CHECK(i2s_channel_reconfig_std_clock(tx_chan, &clk_cfg));
}

static void play_embedded_loop(uint32_t generation)
{
    const uint8_t *wav_data = _binary_audio_wav_start;
    size_t wav_size = _binary_audio_wav_end - _binary_audio_wav_start;

    uint16_t num_channels = 0;
    uint32_t sample_rate = 0;
    uint16_t bits_per_sample = 0;
    uint32_t data_size = 0;

    const uint8_t *pcm_data = audio_parse_wav(wav_data, wav_size,
                                               &num_channels, &sample_rate,
                                               &bits_per_sample, &data_size);
    if (pcm_data == NULL || bits_per_sample != 16 || data_size == 0 ||
        (num_channels != 1 && num_channels != 2) || sample_rate < 8000 || sample_rate > 48000) {
        ESP_LOGE(TAG, "Bad embedded WAV");
        vTaskDelay(pdMS_TO_TICKS(1000));
        return;
    }

    reconfigure_sample_rate(sample_rate);

    size_t bytes_per_frame = (bits_per_sample / 8U) * num_channels;
    if (data_size % bytes_per_frame != 0) {
        ESP_LOGE(TAG, "Embedded WAV data is not aligned to a complete sample frame");
        return;
    }
    size_t samples_per_chunk = (sample_rate * AUDIO_CHUNK_MS) / 1000U;
    size_t bytes_per_chunk = samples_per_chunk * bytes_per_frame;
    const size_t preload_capacity = AUDIO_DMA_DESC_NUM * AUDIO_DMA_FRAME_NUM;
    size_t pcm_capacity = samples_per_chunk > preload_capacity ? samples_per_chunk : preload_capacity;
    uint8_t *raw_buf = (uint8_t *)calloc(1, bytes_per_chunk);
    int16_t *pcm_buf = (int16_t *)calloc(pcm_capacity, sizeof(int16_t));
    assert(raw_buf && pcm_buf);

    const size_t fade_samples = (sample_rate * 5) / 1000;
    size_t total_frames = data_size / bytes_per_frame;
    size_t read_pos = 0;
    size_t fade_in_pos = 0;

    /* Preload */
    {
        size_t preload_total = 0;
        while (preload_total < preload_capacity && read_pos < data_size) {
            size_t remaining = data_size - read_pos;
            size_t free_frames = preload_capacity - preload_total;
            size_t frames_to_read = remaining / bytes_per_frame;
            if (frames_to_read > samples_per_chunk) frames_to_read = samples_per_chunk;
            if (frames_to_read > free_frames) frames_to_read = free_frames;
            size_t copy_bytes = frames_to_read * bytes_per_frame;
            if (copy_bytes == 0) break;
            memcpy(raw_buf, pcm_data + read_pos, copy_bytes);
            read_pos += copy_bytes;
            size_t frames = copy_bytes / bytes_per_frame;
            for (size_t i = 0; i < frames && preload_total < preload_capacity; ++i) {
                int16_t sample = convert_sample(raw_buf + i * bytes_per_frame, num_channels);
                if (fade_in_pos < fade_samples) {
                    sample = (int16_t)((sample * (int)fade_in_pos) / (int)fade_samples);
                }
                pcm_buf[preload_total++] = sample;
                fade_in_pos++;
            }
        }
        if (preload_total > 0) {
            size_t written = preload_total * sizeof(int16_t);
            i2s_channel_preload_data(tx_chan, pcm_buf, written, &written);
        }
    }

    if (!request_is_current(AUDIO_EMBEDDED, generation)) {
        free(raw_buf);
        free(pcm_buf);
        return;
    }
    start_output_channel();

    while (1) {
        if (!request_is_current(AUDIO_EMBEDDED, generation)) break;

        if (read_pos >= data_size) {
            read_pos = 0;
            fade_in_pos = 0;
        }

        size_t remaining = data_size - read_pos;
        size_t copy_bytes = (remaining < bytes_per_chunk) ? remaining : bytes_per_chunk;
        size_t chunk_start_frame = read_pos / bytes_per_frame;
        memcpy(raw_buf, pcm_data + read_pos, copy_bytes);
        read_pos += copy_bytes;

        size_t frame_count = copy_bytes / bytes_per_frame;
        size_t sample_count = 0;
        for (size_t i = 0; i < frame_count; ++i) {
            int16_t sample = convert_sample(raw_buf + i * bytes_per_frame, num_channels);
            size_t frame_index = chunk_start_frame + i;
            size_t dist_from_end = total_frames - frame_index - 1;
            if (dist_from_end < fade_samples) {
                sample = (int16_t)((sample * (int)dist_from_end) / (int)fade_samples);
            }
            if (fade_in_pos + i < fade_samples) {
                sample = (int16_t)((sample * (int)(fade_in_pos + i)) / (int)fade_samples);
            }
            pcm_buf[sample_count++] = sample;
        }
        fade_in_pos += sample_count;

        if (!write_pcm(pcm_buf, sample_count, AUDIO_EMBEDDED, generation)) break;
        vTaskDelay(pdMS_TO_TICKS(1));
    }

    free(raw_buf);
    free(pcm_buf);
}

static FILE *sd_file_open(const char *path)
{
    if (!sd_card_lock()) return NULL;
    FILE *file = fopen(path, "rb");
    sd_card_unlock();
    return file;
}

static size_t sd_file_read(FILE *file, void *buffer, size_t size)
{
    if (!sd_card_lock()) return 0;
    size_t read_size = fread(buffer, 1, size, file);
    sd_card_unlock();
    return read_size;
}

static bool sd_file_seek(FILE *file, long offset, int origin)
{
    if (!sd_card_lock()) return false;
    bool success = fseek(file, offset, origin) == 0;
    sd_card_unlock();
    return success;
}

static bool sd_file_tell(FILE *file, long *position)
{
    if (!sd_card_lock()) return false;
    *position = ftell(file);
    sd_card_unlock();
    return *position >= 0;
}

static void sd_file_close(FILE *file)
{
    if (file != NULL && sd_card_lock()) {
        fclose(file);
        sd_card_unlock();
    }
}

static void play_sd_file(const char *path, uint32_t generation, bool *valid_file)
{
    *valid_file = false;
    if (!request_is_current(AUDIO_SD, generation)) return;
    FILE *file = sd_file_open(path);
    if (file == NULL) {
        ESP_LOGE(TAG, "Cannot open %s", path);
        return;
    }

    uint16_t sd_num_channels = 0;
    uint32_t sample_rate = 0;
    uint16_t bits_per_sample = 0;
    uint32_t data_size = 0;
    long data_offset = 0;

    uint8_t riff_header[12];
    if (sd_file_read(file, riff_header, sizeof(riff_header)) != sizeof(riff_header)) {
        ESP_LOGE(TAG, "Failed to read RIFF header from %s", path);
        sd_file_close(file);
        return;
    }
    if (memcmp(riff_header, "RIFF", 4) != 0 || memcmp(riff_header + 8, "WAVE", 4) != 0) {
        ESP_LOGE(TAG, "Not a WAV file: %s", path);
        sd_file_close(file);
        return;
    }

    if (!sd_file_seek(file, 0, SEEK_END)) {
        sd_file_close(file);
        return;
    }
    long file_size;
    if (!sd_file_tell(file, &file_size) || file_size < 12 || !sd_file_seek(file, 12, SEEK_SET)) {
        sd_file_close(file);
        return;
    }
    bool fmt_found = false;

    while (1) {
        char chunk_id[4];
        uint8_t size_bytes[4];
        if (sd_file_read(file, chunk_id, sizeof(chunk_id)) != sizeof(chunk_id) ||
            sd_file_read(file, size_bytes, sizeof(size_bytes)) != sizeof(size_bytes)) {
            ESP_LOGE(TAG, "WAV chunk table is incomplete");
            sd_file_close(file);
            return;
        }
        uint32_t chunk_size = read_le32(size_bytes);
        long chunk_data_pos;
        if (!sd_file_tell(file, &chunk_data_pos) ||
            (uint64_t)chunk_data_pos + chunk_size > (uint64_t)file_size) {
            ESP_LOGE(TAG, "WAV chunk exceeds file size");
            sd_file_close(file);
            return;
        }
        if (memcmp(chunk_id, "fmt ", 4) == 0) {
            uint8_t fmt[16];
            if (chunk_size < sizeof(fmt) || sd_file_read(file, fmt, sizeof(fmt)) != sizeof(fmt)) {
                ESP_LOGE(TAG, "Invalid WAV format chunk");
                sd_file_close(file);
                return;
            }
            uint16_t audio_format = read_le16(fmt);
            sd_num_channels = read_le16(fmt + 2);
            sample_rate = read_le32(fmt + 4);
            bits_per_sample = read_le16(fmt + 14);
            fmt_found = audio_format == 1;
            ESP_LOGI(TAG, "WAV fmt: format=%u ch=%u rate=%lu bits=%u", audio_format, sd_num_channels, sample_rate, bits_per_sample);
        } else if (memcmp(chunk_id, "data", 4) == 0) {
            if (!fmt_found) {
                ESP_LOGE(TAG, "WAV data chunk appeared before a valid PCM format chunk");
                sd_file_close(file);
                return;
            }
            data_offset = chunk_data_pos;
            data_size = chunk_size;
            break;
        }
        long next_chunk = chunk_data_pos + chunk_size + (chunk_size & 1U);
        if (next_chunk > file_size || !sd_file_seek(file, next_chunk, SEEK_SET)) {
            ESP_LOGE(TAG, "Invalid WAV chunk offset");
            sd_file_close(file);
            return;
        }
    }

    if (bits_per_sample != 16 || data_size == 0 ||
        (sd_num_channels != 1 && sd_num_channels != 2) ||
        sample_rate < 8000 || sample_rate > 48000) {
        ESP_LOGE(TAG, "Unsupported WAV: channels=%u rate=%lu bits=%u size=%lu",
                 sd_num_channels, (unsigned long)sample_rate, bits_per_sample, (unsigned long)data_size);
        sd_file_close(file);
        return;
    }

    ESP_LOGI(TAG, "Playing SD: %lu Hz, %u ch, %u-bit, %lu bytes", sample_rate, sd_num_channels, bits_per_sample, (unsigned long)data_size);

    reconfigure_sample_rate(sample_rate);

    size_t bytes_per_frame = (bits_per_sample / 8U) * sd_num_channels;
    if (data_size % bytes_per_frame != 0) {
        ESP_LOGE(TAG, "WAV data chunk is not aligned to a complete sample frame");
        sd_file_close(file);
        return;
    }
    *valid_file = true;
    size_t samples_per_chunk = (sample_rate * AUDIO_CHUNK_MS) / 1000U;
    size_t bytes_per_chunk = samples_per_chunk * bytes_per_frame;
    const size_t preload_capacity = AUDIO_DMA_DESC_NUM * AUDIO_DMA_FRAME_NUM;
    size_t pcm_capacity = samples_per_chunk > preload_capacity ? samples_per_chunk : preload_capacity;
    uint8_t *raw_buf = (uint8_t *)calloc(1, bytes_per_chunk);
    int16_t *pcm_buf = (int16_t *)calloc(pcm_capacity, sizeof(int16_t));
    assert(raw_buf && pcm_buf);

    const size_t fade_samples = (sample_rate * 5) / 1000;

    /* Preload from file */
    if (!sd_file_seek(file, data_offset, SEEK_SET)) {
        *valid_file = false;
        free(raw_buf);
        free(pcm_buf);
        sd_file_close(file);
        return;
    }
    size_t preload_bytes = 0;
    {
        size_t preload_total = 0;
        while (preload_total < preload_capacity && preload_bytes < data_size) {
            size_t free_frames = preload_capacity - preload_total;
            size_t frames_to_read = (data_size - preload_bytes) / bytes_per_frame;
            if (frames_to_read > samples_per_chunk) frames_to_read = samples_per_chunk;
            if (frames_to_read > free_frames) frames_to_read = free_frames;
            size_t want = frames_to_read * bytes_per_frame;
            if (want == 0) break;
            size_t n = sd_file_read(file, raw_buf, want);
            if (n == 0) break;
            size_t frames = n / bytes_per_frame;
            for (size_t i = 0; i < frames && preload_total < preload_capacity; ++i) {
                int16_t sample = convert_sample(raw_buf + i * bytes_per_frame, sd_num_channels);
                if (preload_total < fade_samples) {
                    sample = (int16_t)((sample * (int)preload_total) / (int)fade_samples);
                }
                pcm_buf[preload_total++] = sample;
            }
            preload_bytes += n;
        }
        if (preload_total > 0) {
            size_t written = preload_total * sizeof(int16_t);
            i2s_channel_preload_data(tx_chan, pcm_buf, written, &written);
        }
    }

    if (!request_is_current(AUDIO_SD, generation)) {
        free(raw_buf);
        free(pcm_buf);
        sd_file_close(file);
        return;
    }
    start_output_channel();

    size_t data_remaining = data_size - preload_bytes;
    size_t fade_in_pos = preload_bytes / bytes_per_frame;
    while (data_remaining > 0) {
        if (!request_is_current(AUDIO_SD, generation)) break;

        size_t to_read = data_remaining < bytes_per_chunk ? data_remaining : bytes_per_chunk;
        size_t bytes_read = sd_file_read(file, raw_buf, to_read);
        if (bytes_read == 0) {
            *valid_file = false;
            break;
        }
        data_remaining -= bytes_read;

        size_t frame_count = bytes_read / bytes_per_frame;
        size_t sample_count = 0;

        for (size_t i = 0; i < frame_count; ++i) {
            int16_t sample = convert_sample(raw_buf + i * bytes_per_frame, sd_num_channels);
            if (fade_in_pos < fade_samples) {
                sample = (int16_t)((sample * (int)fade_in_pos) / (int)fade_samples);
            }
            pcm_buf[sample_count++] = sample;
            fade_in_pos++;
        }

        if (!write_pcm(pcm_buf, sample_count, AUDIO_SD, generation)) break;
        vTaskDelay(pdMS_TO_TICKS(1));
    }

    if (data_remaining == 0 && request_is_current(AUDIO_SD, generation)) {
        size_t queued_frames = data_size / bytes_per_frame;
        if (queued_frames > preload_capacity) queued_frames = preload_capacity;
        uint32_t drain_ms = (queued_frames * 1000U + sample_rate - 1U) / sample_rate;
        for (uint32_t waited = 0; waited < drain_ms &&
             request_is_current(AUDIO_SD, generation); waited += 20) {
            vTaskDelay(pdMS_TO_TICKS(20));
        }
    }

    free(raw_buf);
    free(pcm_buf);
    sd_file_close(file);
}

static void audio_player_task(void *arg)
{
    ESP_LOGI(TAG, "Audio player task started");

    while (1) {
        xSemaphoreTake(audio_mutex, portMAX_DELAY);
        audio_mode_t mode = requested_mode;
        uint32_t generation = request_generation;
        char play_path[AUDIO_FILEPATH_MAX] = {0};
        if (mode == AUDIO_SD) {
            memcpy(play_path, current_filepath, sizeof(play_path));
        }
        xSemaphoreGive(audio_mutex);

        if (mode == AUDIO_SD) {
            ESP_LOGI(TAG, "=== Playing SD file: %s ===", play_path);
            bool valid_file = false;
            play_sd_file(play_path, generation, &valid_file);
            ESP_LOGI(TAG, "=== SD playback finished ===");

            xSemaphoreTake(audio_mutex, portMAX_DELAY);
            /* Only the request that started this playback may complete it. */
            if (requested_mode == AUDIO_SD && request_generation == generation &&
                (!loop_sd || !valid_file)) {
                requested_mode = AUDIO_IDLE;
                current_filepath[0] = '\0';
                ++request_generation;
            }
            xSemaphoreGive(audio_mutex);

            stop_output_channel();
            continue;
        }

        if (mode == AUDIO_IDLE) {
            stop_output_channel();
            vTaskDelay(pdMS_TO_TICKS(100));
            continue;
        }

        play_embedded_loop(generation);
        stop_output_channel();
    }
}

/* Public API */

void audio_player_start(void)
{
    audio_mutex = xSemaphoreCreateMutex();
    assert(audio_mutex != NULL);
    requested_mode = AUDIO_IDLE;

    i2s_chan_config_t chan_cfg = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_AUTO, I2S_ROLE_MASTER);
    chan_cfg.dma_desc_num = AUDIO_DMA_DESC_NUM;
    chan_cfg.dma_frame_num = AUDIO_DMA_FRAME_NUM;
    ESP_ERROR_CHECK(i2s_new_channel(&chan_cfg, &tx_chan, NULL));

    i2s_std_config_t std_cfg = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(16000),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(AUDIO_BIT_WIDTH, AUDIO_SLOT_MODE),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = EXAMPLE_I2S_BCLK_IO1,
            .ws   = EXAMPLE_I2S_WS_IO1,
            .dout = EXAMPLE_I2S_DOUT_IO1,
            .din  = I2S_GPIO_UNUSED,
            .invert_flags = {
                .mclk_inv = false,
                .bclk_inv = false,
                .ws_inv   = false,
            },
        },
    };

    ESP_ERROR_CHECK(i2s_channel_init_std_mode(tx_chan, &std_cfg));
    BaseType_t task_created = xTaskCreate(audio_player_task, "audio_player_task", 16384, NULL, 5, NULL);
    assert(task_created == pdPASS);
}

static void set_sd_request(const char *filepath, bool loop)
{
    if (audio_mutex == NULL || filepath == NULL || filepath[0] == '\0') return;

    ESP_LOGI(TAG, "Play requested: %s", filepath);

    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    strncpy(current_filepath, filepath, AUDIO_FILEPATH_MAX - 1);
    current_filepath[AUDIO_FILEPATH_MAX - 1] = '\0';
    requested_mode = AUDIO_SD;
    loop_sd = loop;
    ++request_generation;
    xSemaphoreGive(audio_mutex);
}

void audio_player_play(const char *filepath)
{
    set_sd_request(filepath, false);
}

void audio_player_play_loop(const char *filepath)
{
    set_sd_request(filepath, true);
}

void audio_player_play_embedded(void)
{
    if (!audio_mutex) return;
    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    current_filepath[0] = '\0';
    requested_mode = AUDIO_EMBEDDED;
    ++request_generation;
    xSemaphoreGive(audio_mutex);
}

void audio_player_set_volume(unsigned percent)
{
    if (!audio_mutex) return;
    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    atomic_store(&volume_percent, percent > 100 ? 100 : percent);
    xSemaphoreGive(audio_mutex);
}

void audio_player_stop(void)
{
    if (audio_mutex == NULL) return;

    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    current_filepath[0] = '\0';
    requested_mode = AUDIO_IDLE;
    ++request_generation;
    xSemaphoreGive(audio_mutex);

    ESP_LOGI(TAG, "Stop requested");
}

void audio_player_get_status(bool *playing, char *filepath, size_t filepath_size)
{
    if (playing == NULL || filepath == NULL || filepath_size == 0) return;
    *playing = false;
    filepath[0] = '\0';
    if (audio_mutex == NULL) return;

    xSemaphoreTake(audio_mutex, portMAX_DELAY);
    *playing = requested_mode != AUDIO_IDLE;
    if (requested_mode == AUDIO_SD) {
        snprintf(filepath, filepath_size, "%s", current_filepath);
    } else if (requested_mode == AUDIO_EMBEDDED) {
        snprintf(filepath, filepath_size, "%s", "(embedded audio)");
    }
    xSemaphoreGive(audio_mutex);
}
